  FT["PH-H1096"] = {"id":"PH-H1096","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1955/ra_1262_1955.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定政府各部门与分支机构及政府所有或控制的公司向国会两院立法参考处提供数据与出版物，为此进一步修订《行政法典》第1692条第一段（经修正）的法案","en":"An Act Providing for the Supply of Data and Publications by the Various Offices and Branches of the Government and Government-Owned or Controlled Corporations to the Legislative Reference Division of Each House of Congress by Further Amending the First Paragraph of Section Sixteen Hundred and Ninety-Two of the Administrative Code, as Amended","orig":"An Act Providing for the Supply of Data and Publications by the Various Offices and Branches of the Government and Government-Owned or Controlled Corporations to the Legislative Reference Division of Each House of Congress by Further Amending the First Paragraph of Section Sixteen Hundred and Ninety-Two of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1262","issuingBody":"Congress of the Philippines","promulgatedDate":"1955-06-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1955/ra_1262_1955.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1096-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of section sixteen hundred and ninety-two of Act Numbered Twenty-seven hundred and eleven, as amended, is further amended to read as follows:\n\"Sec. 1692. Data and documents to be supplied to Bureau of Public Libraries and to legislative reference division of each House of Congress. — The various Departments, Bureaus, Offices, and branches of the government, including the provinces and municipalities, and government-owned or controlled corporations, shall furnish without charge to the Director of Public Libraries and to the legislative reference division of each House of Congress all data or information that may be required in the performance of the functions of said institutions and it shall be obligatory on the part of the government office, agency or government-owned or controlled corporation ordering the printing of any publication to deliver to the Bureau of Public Libraries at least two hundred copies of all printed reports or documents of any kind published at the instance of said government office, agency or corporation and to each of the said legislative reference divisions three copies of such of said printed reports or documents as are classified as nonsalable."}},{"id":"PH-H1096-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 10, 1955."}}],"pack":"ph-p15","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Supply of Data and Publications by the Various Offices and Branches of the Government and Government-Owned or Controlled Corporations to the Legislative Reference Division of Each House of Congress by Further Amending the First Paragraph of Section Sixteen Hundred and Ninety-Two of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
